using System;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
public partial class RoadMapEditor {
 Texture2D mapTexture;Color32[] mapPixels;bool rasterizing;string rasterKey="";Vector2 dragStart;bool panning,dragPoint;RoadMapDocument dragBefore;Rect canvas;float canvasScale;
 Vector2 Project(MapPoint p){return new Vector2(canvas.center.x+(p.x-Centre.x)*canvasScale,canvas.center.y-(p.z-Centre.y)*canvasScale);}
 Vector2 Project(Vector3 p){return Project(new MapPoint{x=p.x,z=p.z});}
 Vector3 Unproject(Vector2 p){return new Vector3(Centre.x+(p.x-canvas.center.x)/canvasScale,0,Centre.y-(p.y-canvas.center.y)/canvasScale);}
 void Line(Vector2 a,Vector2 b,Color color,float width){if(!rasterizing||!Clip(ref a,ref b))return;int steps=Mathf.CeilToInt(Mathf.Max(Mathf.Abs(b.x-a.x),Mathf.Abs(b.y-a.y)));int radius=Mathf.Clamp(Mathf.RoundToInt(width*.5f),0,60);Color32 tint=color;for(int n=0;n<=steps;n++){var p=Vector2.Lerp(a,b,steps==0?0:n/(float)steps);int x=Mathf.RoundToInt(p.x),y=Mathf.RoundToInt(p.y);for(int oy=-radius;oy<=radius;oy++)for(int ox=-radius;ox<=radius;ox++){int u=x+ox,v=y+oy;if(u<0||u>=950||v<0||v>=600)continue;mapPixels[(599-v)*950+u]=tint;}}}
 bool Clip(ref Vector2 a,ref Vector2 b){float low=0,high=1;var d=b-a;float[] p={-d.x,d.x,-d.y,d.y};float[] q={a.x,canvas.width-a.x,a.y,canvas.height-a.y};for(int i=0;i<4;i++){if(Mathf.Abs(p[i])<.00001f){if(q[i]<0)return false;continue;}float t=q[i]/p[i];if(p[i]<0)low=Mathf.Max(low,t);else high=Mathf.Min(high,t);if(low>high)return false;}b=a+d*high;a=a+d*low;return true;} void Dot(Vector2 p,Color c,float size){Fill(new Rect(p.x-size/2,p.y-size/2,size,size),c);}
 void Canvas(Rect rect){canvas=new Rect(0,0,rect.width,rect.height);canvasScale=rect.width/Span;GUI.BeginGroup(rect);Fill(canvas,new Color(.12f,.17f,.18f));if(show3D){if(!preview){preview=new GameObject("地图预览").AddComponent<RoadMapPreview>();}preview.Draw(document,Centre,Span);if(preview.Texture)GUI.DrawTexture(canvas,preview.Texture,ScaleMode.ScaleToFit);GUI.EndGroup();return;}
  BeginRaster();foreach(var r in RoadMapRuntime.Baseline.roads)DrawPath(r.points,new Color(.22f,.25f,.27f),Mathf.Max(2,r.width*canvasScale));if(showOriginal)foreach(var l in RoadMapRuntime.Baseline.hdEdges){if(l.disabled)continue;DrawPath(l.points,new Color(.4f,.44f,.46f),1);}
  foreach(var l in document.lanes){if(l.disabled)continue;Color c=l.id==selected?Color.yellow:l.turn<0?new Color(.65f,.5f,1):l.turn>0?new Color(.4f,1,.6f):new Color(.2f,.8f,.9f);DrawPath(l.points,c,l.id==selected?4:2);}
  EndRaster();foreach(var r in session.world.map.junctionRules){var at=Project(r.V());if(canvas.Contains(at)){Dot(at,Color.white,5);GUI.Label(new Rect(at.x+8,at.y-18,190,25),r.id,label);}}
  foreach(var f in document.facilities){var at=Project(f.Position);if(!canvas.Contains(at))continue;Dot(at,f.id==selected?Color.yellow:f.kind.Contains("Signal")?Color.red:Color.white,12);GUI.Label(new Rect(at.x+8,at.y,180,25),f.kind=="sign"?f.type:f.kind,label);}
  var lane=Lane;if(lane!=null)for(int i=0;i<lane.points.Length;i++){var at=Project(lane.points[i]);if(canvas.Contains(at)){Dot(at,i==SelectedPoint?Color.red:Color.white,i==SelectedPoint?12:7);}}
  var ev=Event.current;if(canvas.Contains(ev.mousePosition)){if(ev.type==EventType.ScrollWheel){Span=Mathf.Clamp(Span*Mathf.Pow(1.12f,ev.delta.y),30,2500);ev.Use();}
   if(ev.type==EventType.MouseDown){dragStart=ev.mousePosition;if(ev.button==1||ev.button==2){panning=true;ev.Use();}else if(ev.button==0){if(lane!=null){float best=13;for(int i=0;i<lane.points.Length;i++){float d=Vector2.Distance(Project(lane.points[i]),ev.mousePosition);if(d<best){best=d;SelectedPoint=i;dragPoint=true;}}if(dragPoint)dragBefore=document.Copy();}
    if(!dragPoint){float best=12;string found="";foreach(var f in document.facilities){float d=Vector2.Distance(Project(f.Position),ev.mousePosition);if(d<best){best=d;found=f.id;}}if(found=="")foreach(var l in document.lanes.Where(l=>!l.disabled)){for(int i=1;i<l.points.Length;i++){var a=Project(l.points[i-1]);var b=Project(l.points[i]);var d=b-a;float t=Mathf.Clamp01(Vector2.Dot(ev.mousePosition-a,d)/Mathf.Max(.001f,d.sqrMagnitude));float error=Vector2.Distance(ev.mousePosition,a+d*t);if(error<best){best=error;found=l.id;}}}Select(found);}ev.Use();}}
  }
  if(ev.type==EventType.MouseDrag){if(panning){Centre+=new Vector2(-ev.delta.x,ev.delta.y)/canvasScale;ev.Use();}else if(dragPoint&&Lane!=null){MovePoint(Lane,SelectedPoint,Unproject(ev.mousePosition));ev.Use();}}
  if(ev.type==EventType.MouseUp){if(dragPoint&&dragBefore!=null){history.Commit(dragBefore);document.revision++;notice="제어점 이동 · 미저장";issues.Clear();dragBefore=null;}dragPoint=false;panning=false;}
  GUI.Label(new Rect(12,12,600,26),junction+" · 북쪽 ↑ · "+Span.ToString("0")+"m / 폭",label);GUI.EndGroup();
 }
 void BeginRaster(){if(!mapTexture){mapTexture=new Texture2D(950,600,TextureFormat.RGBA32,false);mapTexture.filterMode=FilterMode.Bilinear;mapPixels=new Color32[950*600];}string key=document.revision+":"+Centre+":"+Span+":"+selected+":"+showOriginal;rasterizing=key!=rasterKey||dragPoint;if(!rasterizing)return;rasterKey=key;var color=new Color32(30,42,45,255);for(int i=0;i<mapPixels.Length;i++)mapPixels[i]=color;} void EndRaster(){if(rasterizing){mapTexture.SetPixels32(mapPixels);mapTexture.Apply(false);}GUI.DrawTexture(canvas,mapTexture,ScaleMode.StretchToFill);} void DrawPath(MapPoint[] points,Color color,float width){if(points==null)return;for(int i=1;i<points.Length;i++){var a=Project(points[i-1]);var b=Project(points[i]);if((a.x<0&&b.x<0)||(a.x>canvas.width&&b.x>canvas.width)||(a.y<0&&b.y<0)||(a.y>canvas.height&&b.y>canvas.height))continue;Line(a,b,color,width);}}
 void MovePoint(RoadMapLane l,int i,Vector3 p){p.x=Mathf.Clamp(p.x,0,session.world.map.width);p.z=Mathf.Clamp(p.z,0,session.world.map.depth);string node=i==0?l.fromNode:i==l.points.Length-1?l.toNode:null;l.points[i]=new MapPoint{x=p.x,z=p.z};if(node!=null)foreach(var n in document.lanes){if(n.fromNode==node)n.points[0]=new MapPoint{x=p.x,z=p.z};if(n.toNode==node)n.points[n.points.Length-1]=new MapPoint{x=p.x,z=p.z};}}
}
